import { IngestPipeline } from "@514labs/moose-lib";

export interface ProductEvent {
  id: string;
  productId: string;
  userId: string;
  eventType: "view" | "add_to_cart" | "purchase";
  timestamp: Date;
  properties: {
    price?: number;
    quantity?: number;
    currency?: string;
    [key: string]: any;
  };
}

// Create ingestion pipeline with proper ordering for analytics queries
export const ProductEventPipeline = new IngestPipeline<ProductEvent>("ProductEvent", {
  table: {
    orderByFields: ["eventType", "timestamp", "productId"]
  },
  stream: true,
  ingestApi: true,
});

