import { MaterializedView } from "@514labs/moose-lib";

export interface TopProductsView {
  productId: string;
  purchaseCount: number;
  totalRevenue: number;
  lastPurchase: Date;
}

export const TopProductsAggregation = new MaterializedView<TopProductsView>("TopProductsView", {
  select: `
    productId,
    count(*) as purchaseCount,
    sum(properties.price) as totalRevenue,
    max(timestamp) as lastPurchase
  `,
  from: "ProductEvent",
  where: "eventType = 'purchase' AND properties.price IS NOT NULL",
  groupBy: ["productId"],
  orderBy: ["purchaseCount DESC", "totalRevenue DESC"],
});

