import { MaterializedView } from "@514labs/moose-lib";

export interface ConversionFunnelView {
  productId: string;
  views: number;
  addToCarts: number;
  purchases: number;
  cartConversionRate: number;
  purchaseConversionRate: number;
}

export const ConversionFunnelAggregation = new MaterializedView<ConversionFunnelView>("ConversionFunnelView", {
  select: `
    productId,
    sumIf(1, eventType = 'view') as views,
    sumIf(1, eventType = 'add_to_cart') as addToCarts,
    sumIf(1, eventType = 'purchase') as purchases,
    if(views > 0, addToCarts / views * 100, 0) as cartConversionRate,
    if(views > 0, purchases / views * 100, 0) as purchaseConversionRate
  `,
  from: "ProductEvent",
  groupBy: ["productId"],
  orderBy: ["purchaseConversionRate DESC"],
});

