    toStartOfHour(timestamp) as hour,
    eventType,
    count(*) as eventCount,
    uniq(userId) as uniqueUsers,
    uniq(productId) as uniqueProducts,
    sumIf(properties.price, eventType = 'purchase' AND properties.price IS NOT NULL) as totalRevenue
  `,
  from: "ProductEvent",
  groupBy: ["hour", "eventType"],
  orderBy: ["hour DESC", "eventType"],
});

