import { Client } from 'pg';
import axios from 'axios';

interface PostgresProductEvent {
  id: string;
  product_id: string;
  user_id: string;
  event_type: string;
  timestamp: string;
  properties: any;
}

interface MooseProductEvent {
  id: string;
  productId: string;
  userId: string;
  eventType: "view" | "add_to_cart" | "purchase";
  timestamp: Date;
  properties: {
    price?: number;
    quantity?: number;
    currency?: string;
    [key: string]: any;
  };
}

const POSTGRES_CONFIG = {
  user: process.env.POSTGRES_USER || 'postgres',
  host: process.env.POSTGRES_HOST || 'localhost',
  database: process.env.POSTGRES_DB || 'analytics',
  password: process.env.POSTGRES_PASSWORD || 'password',
  port: parseInt(process.env.POSTGRES_PORT || '5432'),
};

const MOOSE_INGEST_URL = process.env.MOOSE_INGEST_URL || 'http://localhost:4000/ingest/ProductEvent';

async function extractAndIngestData() {
  const pgClient = new Client(POSTGRES_CONFIG);

  try {
    console.log('Connecting to Postgres...');
    await pgClient.connect();

    console.log('Fetching events from raw.product_events...');
    const result = await pgClient.query(`
      SELECT
        id,
        product_id,
        user_id,
        event_type,
        timestamp,
        properties
      FROM raw.product_events
      ORDER BY timestamp
    `);

    console.log(`Found ${result.rows.length} events to process`);

    const batchSize = 1000;
    let processedCount = 0;

    for (let i = 0; i < result.rows.length; i += batchSize) {
      const batch = result.rows.slice(i, i + batchSize);
      const transformedBatch: MooseProductEvent[] = batch.map((row: PostgresProductEvent) => ({
        id: row.id,
        productId: row.product_id,
        userId: row.user_id,
        eventType: row.event_type as "view" | "add_to_cart" | "purchase",
        timestamp: new Date(row.timestamp),
        properties: row.properties || {},
      }));

      try {
        await axios.post(MOOSE_INGEST_URL, transformedBatch, {
          headers: {
            'Content-Type': 'application/json',
          },
        });

        processedCount += batch.length;
        console.log(`Processed ${processedCount}/${result.rows.length} events`);
      } catch (error) {
        console.error(`Error ingesting batch ${i / batchSize + 1}:`, error);
      }
    }

    console.log(`Successfully ingested ${processedCount} events`);

  } catch (error) {
    console.error('Error during extraction and ingestion:', error);
  } finally {
    await pgClient.end();
  }
}

if (require.main === module) {
  extractAndIngestData().then(() => {
    console.log('Ingestion complete');
    process.exit(0);
  }).catch((error) => {
    console.error('Ingestion failed:', error);
    process.exit(1);
  });
}

export { extractAndIngestData };

