import { Api, sql } from "@514labs/moose-lib";
import { TopProductsTable } from "../aggregations/TopProducts";
import { ConversionFunnelTable } from "../aggregations/ConversionFunnel";
import { HourlyActivityTable } from "../aggregations/HourlyActivity";

// Define response types
export interface TopProductsResponse {
  productId: string;
  purchaseCount: number;
  totalRevenue: number;
  lastPurchase: Date;
}

export interface ConversionFunnelResponse {
  productId: string;
  views: number;
  addToCarts: number;
  purchases: number;
  cartConversionRate: number;
  purchaseConversionRate: number;
}

export interface HourlyActivityResponse {
  hour: Date;
  eventType: string;
  eventCount: number;
  uniqueUsers: number;
  uniqueProducts: number;
  totalRevenue: number;
}

// Top Products API endpoint
export const TopProductsApi = new Api<{}, TopProductsResponse[]>(
  "getTopProducts",
  async (params, { client }) => {
    const result = await client.query.execute(
      sql.statement`
        SELECT
          productId,
          purchaseCount,
          totalRevenue,
          lastPurchase
        FROM ${TopProductsTable}
        ORDER BY purchaseCount DESC, totalRevenue DESC
        LIMIT 100
      `
    );
    return result.data;
  }
);

// Conversion Funnel API endpoint
export const ConversionFunnelApi = new Api<{}, ConversionFunnelResponse[]>(
  "getConversionFunnel",
  async (params, { client }) => {
    const result = await client.query.execute(
      sql.statement`
        SELECT
          productId,
          views,
          addToCarts,
          purchases,
          round(cartConversionRate, 2) as cartConversionRate,
          round(purchaseConversionRate, 2) as purchaseConversionRate
        FROM ${ConversionFunnelTable}
        WHERE views > 0
        ORDER BY purchaseConversionRate DESC
        LIMIT 100
      `
    );
    return result.data;
  }
);

// Hourly Activity API endpoint
export const HourlyActivityApi = new Api<{}, HourlyActivityResponse[]>(
  "getHourlyActivity",
  async (params, { client }) => {
    const result = await client.query.execute(
      sql.statement`
        SELECT
          hour,
          eventType,
          eventCount,
          uniqueUsers,
          uniqueProducts,
          totalRevenue
        FROM ${HourlyActivityTable}
        ORDER BY hour DESC, eventType
        LIMIT 1000
      `
    );
    return result.data;
  }
);

