import { MaterializedView, OlapTable, sql } from "@514labs/moose-lib";
import { ProductEventPipeline } from "../models/ProductEvent";

export interface TopProductsView {
  productId: string;
  purchaseCount: number;
  totalRevenue: number;
  lastPurchase: Date;
}

