  // Product 2 - Medium conversion product
  { id: '6', productId: 'prod_2', userId: 'user_3', eventType: 'view', timestamp: new Date('2026-04-17T12:00:00Z'), properties: {} },
  { id: '7', productId: 'prod_2', userId: 'user_4', eventType: 'view', timestamp: new Date('2026-04-17T12:30:00Z'), properties: {} },
  { id: '8', productId: 'prod_2', userId: 'user_3', eventType: 'add_to_cart', timestamp: new Date('2026-04-17T12:01:00Z'), properties: { quantity: 1 } },
  { id: '9', productId: 'prod_2', userId: 'user_3', eventType: 'purchase', timestamp: new Date('2026-04-17T12:05:00Z'), properties: { price: 49.99, quantity: 1, currency: 'USD' } },

  // Product 3 - Low conversion product
  { id: '10', productId: 'prod_3', userId: 'user_5', eventType: 'view', timestamp: new Date('2026-04-17T13:00:00Z'), properties: {} },
  { id: '11', productId: 'prod_3', userId: 'user_6', eventType: 'view', timestamp: new Date('2026-04-17T13:15:00Z'), properties: {} },
  { id: '12', productId: 'prod_3', userId: 'user_7', eventType: 'view', timestamp: new Date('2026-04-17T13:30:00Z'), properties: {} },
  { id: '13', productId: 'prod_3', userId: 'user_8', eventType: 'view', timestamp: new Date('2026-04-17T13:45:00Z'), properties: {} },
  { id: '14', productId: 'prod_3', userId: 'user_5', eventType: 'add_to_cart', timestamp: new Date('2026-04-17T13:10:00Z'), properties: { quantity: 1 } },

  // More hourly activity data
  { id: '15', productId: 'prod_1', userId: 'user_9', eventType: 'view', timestamp: new Date('2026-04-17T14:00:00Z'), properties: {} },
  { id: '16', productId: 'prod_2', userId: 'user_10', eventType: 'view', timestamp: new Date('2026-04-17T15:00:00Z'), properties: {} },
  { id: '17', productId: 'prod_1', userId: 'user_11', eventType: 'purchase', timestamp: new Date('2026-04-17T16:00:00Z'), properties: { price: 29.99, quantity: 1, currency: 'USD' } },
];

async function createSampleData() {
  try {
    console.log('Creating sample data...');

    // Wait for server to be ready
    await new Promise(resolve => setTimeout(resolve, 5000));

    const response = await axios.post(MOOSE_INGEST_URL, sampleEvents, {
      headers: {
        'Content-Type': 'application/json',
      },
      timeout: 10000,
    });

    console.log(`Successfully created ${sampleEvents.length} sample events`);
    console.log('Response status:', response.status);

    // Wait for data to be processed
    console.log('Waiting for data to be processed...');
    await new Promise(resolve => setTimeout(resolve, 3000));

  } catch (error) {
    console.error('Error creating sample data:', error);
    if (axios.isAxiosError(error) && error.response) {
      console.error('Response data:', error.response.data);
      console.error('Response status:', error.response.status);
    }
  }
}

if (require.main === module) {
  createSampleData().then(() => {
    console.log('Sample data creation complete');
    process.exit(0);
  }).catch((error) => {
    console.error('Sample data creation failed:', error);
    process.exit(1);
  });
}

export { createSampleData };

