const MOOSE_INGEST_URL = 'http://localhost:4000/ingest/ProductEvent';

// Sample product events
const sampleEvents = [
  // Product 1 - High conversion product
  { id: '1', productId: 'prod_1', userId: 'user_1', eventType: 'view', timestamp: new Date('2026-04-17T10:00:00Z'), properties: {} },
  { id: '2', productId: 'prod_1', userId: 'user_1', eventType: 'add_to_cart', timestamp: new Date('2026-04-17T10:01:00Z'), properties: { quantity: 1 } },
  { id: '3', productId: 'prod_1', userId: 'user_1', eventType: 'purchase', timestamp: new Date('2026-04-17T10:02:00Z'), properties: { price: 29.99, quantity: 1, currency: 'USD' } },

  { id: '4', productId: 'prod_1', userId: 'user_2', eventType: 'view', timestamp: new Date('2026-04-17T11:00:00Z'), properties: {} },
  { id: '5', productId: 'prod_1', userId: 'user_2', eventType: 'purchase', timestamp: new Date('2026-04-17T11:01:00Z'), properties: { price: 29.99, quantity: 2, currency: 'USD' } },

  // Product 2 - Medium conversion product
  { id: '6', productId: 'prod_2', userId: 'user_3', eventType: 'view', timestamp: new Date('2026-04-17T12:00:00Z'), properties: {} },
  { id: '7', productId: 'prod_2', userId: 'user_4', eventType: 'view', timestamp: new Date('2026-04-17T12:30:00Z'), properties: {} },
  { id: '8', productId: 'prod_2', userId: 'user_3', eventType: 'add_to_cart', timestamp: new Date('2026-04-17T12:01:00Z'), properties: { quantity: 1 } },
  { id: '9', productId: 'prod_2', userId: 'user_3', eventType: 'purchase', timestamp: new Date('2026-04-17T12:05:00Z'), properties: { price: 49.99, quantity: 1, currency: 'USD' } },

  // Product 3 - Low conversion product
  { id: '10', productId: 'prod_3', userId: 'user_5', eventType: 'view', timestamp: new Date('2026-04-17T13:00:00Z'), properties: {} },
  { id: '11', productId: 'prod_3', userId: 'user_6', eventType: 'view', timestamp: new Date('2026-04-17T13:15:00Z'), properties: {} },
  { id: '12', productId: 'prod_3', userId: 'user_7', eventType: 'view', timestamp: new Date('2026-04-17T13:30:00Z'), properties: {} },
  { id: '13', productId: 'prod_3', userId: 'user_8', eventType: 'view', timestamp: new Date('2026-04-17T13:45:00Z'), properties: {} },
  { id: '14', productId: 'prod_3', userId: 'user_5', eventType: 'add_to_cart', timestamp: new Date('2026-04-17T13:10:00Z'), properties: { quantity: 1 } },

  // More hourly activity data
  { id: '15', productId: 'prod_1', userId: 'user_9', eventType: 'view', timestamp: new Date('2026-04-17T14:00:00Z'), properties: {} },
  { id: '16', productId: 'prod_2', userId: 'user_10', eventType: 'view', timestamp: new Date('2026-04-17T15:00:00Z'), properties: {} },
  { id: '17', productId: 'prod_1', userId: 'user_11', eventType: 'purchase', timestamp: new Date('2026-04-17T16:00:00Z'), properties: { price: 29.99, quantity: 1, currency: 'USD' } },
];

async function createSampleData() {
  try {
    console.log('Creating sample data...');

    // Wait for server to be ready
    await new Promise(resolve => setTimeout(resolve, 5000));

    const response = await axios.post(MOOSE_INGEST_URL, sampleEvents, {
      headers: {
        'Content-Type': 'application/json',
      },
      timeout: 10000,
    });

    console.log(`Successfully created ${sampleEvents.length} sample events`);
    console.log('Response status:', response.status);

    // Wait for data to be processed
    console.log('Waiting for data to be processed...');
    await new Promise(resolve => setTimeout(resolve, 3000));

  } catch (error) {
    console.error('Error creating sample data:', error);
    if (axios.isAxiosError(error) && error.response) {
      console.error('Response data:', error.response.data);
      console.error('Response status:', error.response.status);
    }
  }
}

if (require.main === module) {
  createSampleData().then(() => {
    console.log('Sample data creation complete');
    process.exit(0);
  }).catch((error) => {
    console.error('Sample data creation failed:', error);
    process.exit(1);
  });
}

export { createSampleData };

import express from 'express';
import axios from 'axios';

const app = express();
const PORT = 3000;
const MOOSE_BASE_URL = 'http://localhost:4000';

app.use(express.json());

// Add CORS headers
app.use((req, res, next) => {
  res.header('Access-Control-Allow-Origin', '*');
  res.header('Access-Control-Allow-Headers', 'Origin, X-Requested-With, Content-Type, Accept');
  res.header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
  next();
});

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Top products endpoint
app.get('/api/top-products', async (req, res) => {
  try {
    console.log('Fetching top products...');
    const response = await axios.get(`${MOOSE_BASE_URL}/api/getTopProducts`);
    res.json(response.data);
  } catch (error) {
    console.error('Error fetching top products:', error);
    if (axios.isAxiosError(error) && error.response) {
      res.status(error.response.status).json(error.response.data);
    } else {
      res.status(500).json({ error: 'Internal server error', message: String(error) });
    }
  }
});

// Conversion funnel endpoint
app.get('/api/funnel', async (req, res) => {
  try {
    console.log('Fetching conversion funnel...');
    const response = await axios.get(`${MOOSE_BASE_URL}/api/getConversionFunnel`);
    res.json(response.data);
  } catch (error) {
    console.error('Error fetching conversion funnel:', error);
    if (axios.isAxiosError(error) && error.response) {
      res.status(error.response.status).json(error.response.data);
    } else {
      res.status(500).json({ error: 'Internal server error', message: String(error) });
    }
  }
});

// Hourly activity endpoint
app.get('/api/hourly', async (req, res) => {
  try {
    console.log('Fetching hourly activity...');
    const response = await axios.get(`${MOOSE_BASE_URL}/api/getHourlyActivity`);
    res.json(response.data);
  } catch (error) {
    console.error('Error fetching hourly activity:', error);
    if (axios.isAxiosError(error) && error.response) {
      res.status(error.response.status).json(error.response.data);
    } else {
      res.status(500).json({ error: 'Internal server error', message: String(error) });
    }
  }
});

// Start the server
app.listen(PORT, () => {
  console.log(`🚀 Product Analytics API server running on http://localhost:${PORT}`);
  console.log('Available endpoints:');
  console.log(`  GET /api/top-products - Top products by purchase count with revenue`);
  console.log(`  GET /api/funnel - Conversion funnel (views → carts → purchases)`);
  console.log(`  GET /api/hourly - Hourly activity breakdown`);
  console.log(`  GET /health - Health check`);
});

export default app;

